package dev.codex.lastzhelper;
import java.io.*;import java.nio.file.*;import org.json.*;
public final class OwnershipProtocolTests {
 static int checks;static void expect(boolean b,String why){if(!b)throw new AssertionError(why);checks++;}
 static String probe(File dir)throws Exception{Process p=new ProcessBuilder(new File(System.getProperty("java.home"),"bin/java").getPath(),"-cp",System.getProperty("java.class.path"),"dev.codex.lastzhelper.OwnershipLockProbe",dir.getPath()).redirectErrorStream(true).start();String s=new String(p.getInputStream().readAllBytes(),"UTF-8").trim();if(p.waitFor()!=0)throw new IOException(s);return s;}
 public static void main(String[] args)throws Exception{
  File dir=Files.createTempDirectory("lastz-owned-protocol-").toFile();String token="aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa",nonce="bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb";File marker=new File(dir,"legacy-input.json");
  try{String request=new JSONObject().put("token",token).put("nonce",nonce).put("action","shell").put("command","fixture").toString()+"\n";ByteArrayOutputStream text=new ByteArrayOutputStream();
   LegacyOwnershipSession.run(dir,token,new BufferedReader(new StringReader(request)),new PrintStream(text,true,"UTF-8"),command->{expect(command.equals("fixture"),"exact requested command");expect(new JSONObject(StateProbe.text(marker.getPath())).getBoolean("pending"),"fence saved before command");expect(probe(dir).equals("busy"),"separate native process cannot acquire input lock");return "done";},()->System.nanoTime()/1000000);
   expect(!new JSONObject(StateProbe.text(marker.getPath())).getBoolean("pending"),"completion clears fence only after command");expect(probe(dir).equals("free"),"lease released after EOF");String[] lines=text.toString("UTF-8").trim().split("\n");expect(lines.length==2,"ready plus exactly one receipt");JSONObject receipt=new JSONObject(lines[1]);expect(receipt.getString("nonce").equals(nonce)&&receipt.getString("stdout").equals("done"),"matching command acknowledgment");
   boolean failed=false;try{LegacyOwnershipSession.run(dir,token,new BufferedReader(new StringReader(request)),new PrintStream(new ByteArrayOutputStream()),command->{throw new IOException("injected transport/command failure");},()->System.nanoTime()/1000000);}catch(IOException e){failed=true;}expect(failed&&new JSONObject(StateProbe.text(marker.getPath())).getBoolean("pending"),"failed input stays fenced");expect(probe(dir).equals("free"),"dead owner releases kernel lock");failed=false;try{ControllerOwnership.check(marker);}catch(IOException e){failed=true;}expect(failed,"pending receipt still blocks native takeover after owner exits");
   RotationFiles.write(marker,new JSONObject().put("schema",1).put("pending",false));String bad=new JSONObject(request).put("token","cccccccccccccccccccccccccccccccc").toString()+"\n";final boolean[] ran={false};failed=false;try{LegacyOwnershipSession.run(dir,token,new BufferedReader(new StringReader(bad)),new PrintStream(new ByteArrayOutputStream()),command->{ran[0]=true;return "wrong";},()->System.nanoTime()/1000000);}catch(IOException e){failed=true;}expect(failed&&!ran[0],"wrong token cannot issue input");
   System.out.println("Shared Python/native ownership protocol: "+checks+" checks passed; real cross-process locks, no device access");
  }finally{for(File f:dir.listFiles())f.delete();dir.delete();}
 }
}
